@module keyDispatch  src=keyDispatch.lua  loc=103  mode=namespace  self=keyDispatch

# Invariants & contracts
  @contract  returns early (no dispatch) when state.suppressKbd or not state.acceptCmds  @ 57
  @contract  state.pageSuppressed shrinks the walk to the root keymap only — body-region editors (swing, tuning) suppress page bindings without shadowing globals like playPause/quit  @ 58
  @contract  first-hit wins; false declines, releases the key, and lets the page char queue see it  @ 59
  @contract  while cmgr:isPrefixActive(), digits and '/' are captured (no dispatch); Esc cancels; any other key freezes the prefix and falls through to the keychain walk so commands can consumePrefix()  @ 60
  @contract  while captureLetter is declared, that sink gets bare/Shift letters, not the keychain  @ 61

# Shapes
  @shape  dispatchResult = { consumed: bool, commandHeld: { [imguiKey]=true } } — commandHeld holds keys down AND command-bound for the live chord  @ 56

# Imports
  @const ImGui = 'imgui'  @ 8

# Module-level constants
  @const keyDispatch = {}  @ 10

# Private functions
  @fn isDigitMods(mods)  @ 21-23
      -- Capture digits and '/' into the prefix buffer; Esc cancels. Returns
      -- 'consumed' if a prefix-accumulating key fired this frame; nil otherwise
      -- (so the normal keychain walk proceeds). The prefix is NOT finished here
      -- on fall-through: dispatchKeys calls finishPrefix only at the moment a
      -- bound command is about to fire, so idle frames don't kill the buffer.
      -- In prefix mode, digit keys count even with Ctrl/Super held: holding the
      -- chord open while typing a count is a natural reach, and any Ctrl-N or
      -- Super-N command binding is overridden for the duration of prefix mode.
      -- Shift/Alt still disqualify (Shift-digit emits a different char).
  @fn handlePrefixCapture(cmgr, ctx)  @ 25-40
  @fn handleLetterCapture(cmgr, ctx)  @ 44-54
      -- A scope may declare a letter sink (the lotus menu's walk). A bare letter goes to it,
      -- never the keychain; Shift is tolerated since the menu draws uppercase letters.

# Public API (keyDispatch.*)
  @api keyDispatch.dispatchKeys(state, cmgr, ctx)  @ 62-101

# Uses (outbound edges)
  @use call    ImGui.GetKeyMods  @ handlePrefixCapture:27 handleLetterCapture:47 dispatchKeys:74
  @use call    ImGui.IsKeyDown  @ dispatchKeys:81
  @use call    ImGui.IsKeyPressed  @ handlePrefixCapture:29,33,36 handleLetterCapture:49 dispatchKeys:84
  @use require imgui  @ <load>:8

# Calls (intra-file)
  @call handleLetterCapture  @ dispatchKeys:70
  @call handlePrefixCapture  @ dispatchKeys:66
  @call isDigitMods  @ handlePrefixCapture:29,33

# Unresolved receivers
  @drop cmgr:appendPrefix  @ handlePrefixCapture:30,34
  @drop cmgr:cancelPrefix  @ handlePrefixCapture:37
  @drop cmgr:finishPrefix  @ dispatchKeys:88
  @drop cmgr:invoke  @ dispatchKeys:90
  @drop cmgr:isPrefixActive  @ handlePrefixCapture:26 dispatchKeys:87
  @drop cmgr:keySpec  @ dispatchKeys:79
  @drop cmgr:keychain  @ dispatchKeys:75
  @drop cmgr:letterCapture  @ handleLetterCapture:45
  @drop cmgr:rootKeymap  @ dispatchKeys:75

# REAPER API surface
  @reaper ImGui_GetBuiltinPath
  @reaper MB

# Fields (r read / w write incl. constructor keys)
  @field r ImGui_GetBuiltinPath  @ 4
  @field r Key_0  @ handlePrefixCapture:29
  @field r Key_A  @ handleLetterCapture:49
  @field r Key_Escape  @ handlePrefixCapture:36
  @field r Key_Slash  @ handlePrefixCapture:33
  @field r Mod_Ctrl  @ isDigitMods:22
  @field r Mod_Shift  @ handleLetterCapture:47
  @field r Mod_Super  @ isDigitMods:22
  @field r acceptCmds  @ dispatchKeys:63
  @field w commandHeld  @ dispatchKeys:64,68,71,93,100
  @field w consumed  @ dispatchKeys:64,68,71,93,100
  @field w dispatchKeys  @ dispatchKeys:62
  @field r pageSuppressed  @ dispatchKeys:75
  @field r path  @ 7
  @field w path  @ 7
  @field r suppressKbd  @ dispatchKeys:63
